"""Generate a schema-only ERD from the live local database; no row content is exported."""
import argparse,json,re
from pathlib import Path
from .deployment import connect
from .final_schema import snapshot

LABELS=dict(employees='직원·로그인 계정',institutions='기관',departments='부서 계층',job_grades='직급',employee_skills='보유 스킬',employee_certifications='보유 자격증',employee_education_records='학력',skill_tags='스킬 태그',jobs='직무',majors='전공',courses='강좌',books='도서',certifications='자격증',projects='프로젝트·계획',diagnostic_rounds='진단 회차',assessment_questions='설문 문항',assessment_responses='설문 응답',roadmaps='선택 로드맵',roadmap_steps='로드맵 단계',roadmap_step_resources='단계별 학습 자료',roadmap_comments='부서장 코멘트',growth_reports='성장 보고서',prompt_versions='운영 프롬프트',learning_resource_embeddings='학습 자료·스킬 벡터',regulations='규정',regulation_versions='규정 버전',regulation_files='규정 출처 파일',regulation_nodes='규정 원문 구조',regulation_scopes='규정 적용 범위',regulation_references='규정 참조',rag_chunks='규정 검색 청크',rag_chunk_sources='청크 원문 출처',rag_chunk_embeddings='규정 청크 벡터',evaluation_result_schemas='평가기준 체계',evaluation_item_definitions='평가기준 항목',evaluation_schema_sources='평가기준 출처',catalog_api_sources='API 원본·매칭 이력',schema_migrations='스키마 적용 이력',course_skills='강좌 스킬',book_skills='도서 스킬',certification_skills='자격증 스킬',job_skills='직무 스킬',major_skills='전공 스킬',agent_generations='과거 에이전트 생성',agent_selections='과거 선택',finetuning_datasets='과거 데이터셋 이력',preference_pairs='과거 선호 쌍',roadmap_requests='과거 요청',test_mock_profiles='테스트 프로필')

def render(c,template,output):
 data=snapshot(c)
 for key,spec in data.items():
  spec['label']=LABELS.get(key.split('.')[1],key.split('.')[1])
  spec['rows']=c.execute('SELECT count(*) AS n FROM '+key).fetchone()['n']
 css=re.search(r'<style>(.*?)</style>',template.read_text(encoding='utf-8'),re.S).group(1)
 html=HTML.replace('__CSS__',css).replace('__DATA__',json.dumps(data,ensure_ascii=False,default=str).replace('<',chr(92)+'u003c'))
 output.write_text(html,encoding='utf-8')
 return {'file':str(output),'tables':len(data),'foreign_keys':sum(len(s['fks']) for s in data.values())}

HTML=r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GrowPath ERD 최종</title><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;600&family=IBM+Plex+Sans+KR:wght@400;600;700&display=swap"><style>__CSS__
html,body{width:100%;height:100%;margin:0;overflow:hidden}body{display:flex;flex-direction:column;min-width:0}.bar{position:relative;flex:none;z-index:10;width:100%;min-width:0}.bar h1{font-size:16px}.tabs button[aria-pressed="true"]{background:var(--card);color:var(--ink);box-shadow:var(--shadow)}#search{max-width:160px;border:1px solid var(--line-soft);border-radius:6px;background:var(--card);color:var(--ink);padding:4px 8px;font:inherit}#viewport{position:relative;flex:1;min-height:0;overflow:auto;display:block}#stage{position:relative;width:max-content;height:max-content;padding:0}#canvas{position:relative;display:grid;grid-template-columns:repeat(3,max-content);grid-template-areas:none;align-items:start;gap:56px 64px;padding:64px;transform-origin:0 0}.panel{grid-area:auto;min-width:310px}.pbody{display:grid;grid-template-columns:repeat(2,250px);gap:22px 38px}.card{width:250px;position:relative;inset:auto}.ch{cursor:pointer}.ch b{display:block}.meta{display:block}.row{display:grid;grid-template-columns:35px 1fr 78px;gap:4px;padding:3px 10px;font-size:11px}.row .nm{overflow-wrap:anywhere;white-space:normal}.row .ty{max-width:78px;text-align:right}.row .key{color:var(--fk);font-size:9px}.card.compact .plain{display:none}.card:not(.compact) .plain{display:grid}.card.dim{opacity:.16}.card.focus{outline:2px solid var(--pc)}#links{position:absolute;left:0;top:0;z-index:1;overflow:visible;pointer-events:none}#links path{fill:none;stroke:var(--fk);stroke-width:1.4;opacity:.5;pointer-events:stroke}#links path.focus{stroke-width:2.8;opacity:1}#details{position:fixed;right:12px;bottom:12px;width:min(580px,95vw);max-height:45vh;overflow:auto;background:var(--panel);padding:16px;z-index:8;border:1px solid var(--line-soft);border-radius:8px;box-shadow:var(--shadow)}#details pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px}#details[hidden]{display:none}.hint{width:100%;font-size:12px;color:var(--muted)}

</style></head><body><header class="bar"><div><h1>GrowPath · ERD 최종</h1><div class="sub" id="summary"></div></div><nav class="tabs"><button data-view="active">운영 구조</button><button data-view="meta">관리 구조</button><button data-view="archive">보관 구조</button></nav><div class="ctl"><input id="search" aria-label="테이블 검색" placeholder="테이블 검색"><label><input type="checkbox" id="all">모든 열</label><button id="minus">−</button><span id="zoom">100%</span><button id="plus">+</button><button id="fit">화면에 맞춤</button><button id="theme">다크/라이트</button><button id="reset">선택 해제</button><button id="list">테이블 목록</button></div><div class="hint">PK 기본키 · FK 외래키 · NN 필수 값 · 연결선은 실제 외래키입니다. 테이블을 선택하면 관련 구조와 제약조건을 확인할 수 있습니다.</div></header><main id="viewport"><div id="stage"><div id="canvas"><svg id="links" aria-hidden="true"></svg></div></div></main><aside id="details" hidden></aside><script>
const D=__DATA__;
const canvas=document.querySelector('#canvas'),svg=document.querySelector('#links'),detail=document.querySelector('#details');let view='active',scale=1,selected=null;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kind=k=>k.startsWith('growpath_legacy.')?'archive':k.startsWith('growpath_meta.')?'meta':'active';
const group=k=>{let n=k.split('.')[1];if(k.startsWith('growpath_legacy.'))return ['archive','보관 구조','c7'];if(k.startsWith('growpath_meta.'))return ['meta','관리 구조','c7'];if(k.startsWith('regulations.')){if(n.startsWith('evaluation_'))return ['criteria','규정 평가기준·출처','c6'];if(n.startsWith('rag_'))return ['rag','규정 벡터 검색·출처','c5'];return ['regulations','규정 원문·버전·적용 범위','c4']}if(['employees','institutions','departments','job_grades'].includes(n)||n.startsWith('employee_'))return ['people','기관·부서·직원','c1'];if(['projects','diagnostic_rounds','assessment_questions','assessment_responses'].includes(n))return ['diagnosis','프로젝트·설문·진단','c3'];if(['roadmaps','roadmap_steps','roadmap_step_resources','roadmap_comments','growth_reports','prompt_versions'].includes(n))return ['roadmap','로드맵·성장 보고서·프롬프트','c2'];return ['resources','스킬·직무·학습 자료','c5']};
const relations=Object.entries(D).flatMap(([k,s])=>s.fks.map(f=>({from:k,to:f.target,columns:f.columns,target_columns:f.target_columns,name:f.name})));
function focus(k){selected=k;for(const card of canvas.querySelectorAll('.card')){let related=card.dataset.table===k||relations.some(r=>(r.from===k&&r.to===card.dataset.table)||(r.to===k&&r.from===card.dataset.table));card.classList.toggle('dim',!related);card.classList.toggle('focus',card.dataset.table===k)}let s=D[k];detail.hidden=false;detail.innerHTML='<button id="close">닫기</button><h3>'+esc(s.label)+'</h3><p>'+esc(k)+'</p><pre>'+esc(s.constraints.map(c=>c.name+'\n'+c.definition).join('\n\n'))+'</pre>';detail.querySelector('button').onclick=reset;draw()}
function listTables(){detail.hidden=false;let cards=[...canvas.querySelectorAll('.card')];detail.innerHTML='<button id="close">닫기</button><h3>현재 표시 '+cards.length+'개 / 전체 '+Object.keys(D).length+'개</h3><ol>'+cards.map(c=>'<li style="margin:8px 0;overflow-wrap:anywhere">'+esc(D[c.dataset.table].label)+'<br><code>'+esc(c.dataset.table)+'</code></li>').join('')+'</ol>';detail.querySelector('button').onclick=()=>{detail.hidden=true}}
function reset(){selected=null;detail.hidden=true;for(const c of canvas.querySelectorAll('.card'))c.classList.remove('dim','focus');draw()}
function render(){selected=null;detail.hidden=true;canvas.querySelectorAll('.panel').forEach(c=>c.remove());let panels={};let search=document.querySelector('#search').value.trim().toLowerCase();for(const [k,s] of Object.entries(D)){if(kind(k)!==view||!(`${k} ${s.label}`.toLowerCase().includes(search)))continue;let card=document.createElement('section');card.className='card'+(document.querySelector('#all').checked?'':' compact');card.dataset.table=k;let fk=new Set(s.fks.flatMap(f=>f.columns));card.innerHTML='<div class="ch"><b>'+esc(s.label)+'</b><span class="meta">'+esc(k)+'</span><span class="sub">'+s.rows+'행</span></div>'+s.columns.map(c=>{let pk=s.pk.includes(c.column),f=fk.has(c.column);return '<div class="row '+((pk||f)?'':'plain')+'" data-column="'+esc(c.column)+'"><span class="key">'+(pk?'PK ':f?'FK ':'')+(c.not_null?'NN':'')+'</span><span class="nm">'+esc(c.column)+'</span><span class="ty">'+esc(c.type)+'</span></div>'}).join('');card.querySelector('.ch').onclick=()=>focus(k);let [id,title,color]=group(k);if(!panels[id]){let panel=document.createElement('section');panel.className='panel';panel.style.setProperty('--pc','var(--'+color+')');panel.innerHTML='<div class="ptitle">'+esc(title)+'</div><div class="pbody"></div>';panels[id]=panel;canvas.appendChild(panel)}panels[id].querySelector('.pbody').appendChild(card)}for(const p of Object.values(panels)){let count=p.querySelectorAll('.card').length;p.querySelector('.ptitle').innerHTML+='<small>'+count+'개 표</small>';if(count<3)p.querySelector('.pbody').style.gridTemplateColumns='250px'}let counts={active:0,meta:0,archive:0};Object.keys(D).forEach(k=>counts[kind(k)]++);document.querySelector('#summary').textContent=`로컬 PostgreSQL · 운영 ${counts.active}개 / 관리 ${counts.meta}개 / 보관 ${counts.archive}개 · 전체 ${Object.keys(D).length}개 · 현재 표시 ${canvas.querySelectorAll('.card').length}개 · 2026-10-20`;for(const b of document.querySelectorAll('[data-view]'))b.setAttribute('aria-pressed',String(b.dataset.view===view));requestAnimationFrame(()=>{fit();document.querySelector('#viewport').scrollTo(0,0)})}
function draw(){svg.replaceChildren();let cards=Object.fromEntries([...canvas.querySelectorAll('.card')].map(c=>[c.dataset.table,c]));let root=canvas.getBoundingClientRect();svg.setAttribute('width',canvas.scrollWidth);svg.setAttribute('height',canvas.scrollHeight);for(const r of relations){let a=cards[r.from],b=cards[r.to];if(!a||!b)continue;let ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();let al=(ar.left-root.left)/scale,ax=(ar.right-root.left)/scale,bl=(br.left-root.left)/scale,bx=(br.right-root.left)/scale;let y1=(ar.top-root.top+25)/scale,y2=(br.top-root.top+25)/scale;let x1,x2,c1,c2;if(ax+16<bl){x1=ax;x2=bl;let d=Math.max(30,(x2-x1)*.4);c1=x1+d;c2=x2-d}else if(bx+16<al){x1=al;x2=bx;let d=Math.max(30,(x1-x2)*.4);c1=x1-d;c2=x2+d}else{x1=ax;x2=bx;c1=c2=Math.max(ax,bx)+38}let path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',`M${x1},${y1} C${c1},${y1} ${c2},${y2} ${x2},${y2}`);if(selected&&(r.from===selected||r.to===selected))path.classList.add('focus');let title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=r.from+' ('+r.columns.join(', ')+') → '+r.to+' ('+r.target_columns.join(', ')+')';path.appendChild(title);svg.appendChild(path)}}
function zoom(delta){scale=Math.max(.3,Math.min(1.6,scale+delta));canvas.style.transform=`scale(${scale})`;document.querySelector('#stage').style.width=(canvas.offsetWidth*scale)+'px';document.querySelector('#stage').style.height=(canvas.offsetHeight*scale)+'px';document.querySelector('#zoom').textContent=Math.round(scale*100)+'%';draw()}
function fit(){let vp=document.querySelector('#viewport');zoom(Math.min(1,(vp.clientWidth-24)/canvas.offsetWidth)-scale);vp.scrollTo(0,0)}
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{view=b.dataset.view;render()};document.querySelector('#list').onclick=listTables;document.querySelector('#search').oninput=render;document.querySelector('#all').onchange=render;document.querySelector('#reset').onclick=reset;document.querySelector('#fit').onclick=fit;document.querySelector('#minus').onclick=()=>zoom(-.1);document.querySelector('#plus').onclick=()=>zoom(.1);document.querySelector('#theme').onclick=()=>{let dark=document.documentElement.dataset.theme==='dark'||(!document.documentElement.dataset.theme&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.dataset.theme=dark?'light':'dark'};window.addEventListener('resize',draw);render();
</script></body></html>'''

def main():
 parser=argparse.ArgumentParser();parser.add_argument('--template',type=Path,required=True);parser.add_argument('--output',type=Path,default=Path(__file__).resolve().parents[3]/'docs/ERD_최종.html');args=parser.parse_args()
 with connect('SUPABASE_DB_URL') as c:
  c.execute('SET TRANSACTION READ ONLY');print(json.dumps(render(c,args.template,args.output),ensure_ascii=False))
if __name__=='__main__':main()
